worker_processes 1;
pid /tmp/nginx.pid;
error_log /dev/stderr warn;
events { worker_connections 1024; }

stream {
    set_real_ip_from 192.168.255.0/24;
    set_real_ip_from 127.0.0.1;
    proxy_connect_timeout 5s;
    proxy_timeout 24h;
    # NodeBalancer TCP checks carry its private address, not a player address.
    geo $proxy_protocol_addr $balancer_health_check {
        default 0;
        192.168.255.0/24 1;
    }
    map $balancer_health_check $mud_backend {
        default 127.0.0.1:4003;
        1 127.0.0.1:9081;
    }
    server {
        listen 127.0.0.1:9081;
        return '';
    }
    server {
        listen 14000 proxy_protocol;
        proxy_pass $mud_backend;
        proxy_protocol on;
    }
    server {
        listen 14001 ssl proxy_protocol;
        ssl_certificate /run/savsoul-tls/server.crt;
        ssl_certificate_key /run/savsoul-tls/server.key;
        ssl_protocols TLSv1.2 TLSv1.3;
        proxy_pass $mud_backend;
        proxy_protocol on;
    }
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    access_log off;
    server_tokens off;
    client_max_body_size 32m;
    client_body_temp_path /tmp/client;
    proxy_temp_path /tmp/proxy;
    fastcgi_temp_path /tmp/fastcgi;
    uwsgi_temp_path /tmp/uwsgi;
    scgi_temp_path /tmp/scgi;
    set_real_ip_from 192.168.255.0/24;
    set_real_ip_from 127.0.0.1;
    real_ip_header proxy_protocol;
    map $http_upgrade $connection_upgrade { default upgrade; '' close; }

    server {
        listen 9080;
        location = /healthz { access_log off; return 200 'ready\n'; }
        location / { return 404; }
    }
    server {
        listen 8080 proxy_protocol default_server;
        root /var/www/lpmud;
        index index.html;
        location ~ /\. { deny all; }
        location / { try_files $uri $uri/ =404; }
    }
    server {
        listen 8080 proxy_protocol;
        server_name savsoul.com www.savsoul.com;
        return 301 https://$host$request_uri;
    }
    server {
        listen 8443 ssl proxy_protocol;
        server_name savsoul.com www.savsoul.com;
        ssl_certificate /run/savsoul-tls/server.crt;
        ssl_certificate_key /run/savsoul-tls/server.key;
        ssl_protocols TLSv1.2 TLSv1.3;
        root /var/www/lpmud;
        index index.html;
        add_header X-Content-Type-Options nosniff always;
        add_header Referrer-Policy same-origin always;
        location ~ /\. { deny all; }
        location = /playnow.html {
            add_header X-Content-Type-Options nosniff always;
            add_header Referrer-Policy same-origin always;
            add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self'; img-src 'self' data:; connect-src 'self' wss://savsoul.com wss://www.savsoul.com; object-src 'none'; base-uri 'self'; frame-ancestors 'self'" always;
            add_header Cache-Control no-cache always;
        }
        location = /mud-websocket {
            proxy_pass http://127.0.0.1:4086;
            proxy_http_version 1.1;
            proxy_set_header Host $http_host;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection $connection_upgrade;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Savsoul-Client-IP '';
            proxy_read_timeout 24h;
        }
        location / { try_files $uri $uri/ =404; }
    }
    server {
        listen 14080 proxy_protocol;
        return 301 https://$host:4081$request_uri;
    }
    server {
        listen 14481 ssl proxy_protocol;
        server_name savsoul.com www.savsoul.com;
        ssl_certificate /run/savsoul-tls/server.crt;
        ssl_certificate_key /run/savsoul-tls/server.key;
        ssl_protocols TLSv1.2 TLSv1.3;
        location / {
            proxy_pass http://127.0.0.1:4085;
            proxy_set_header Host $http_host;
            proxy_set_header X-Forwarded-For $remote_addr;
            proxy_set_header X-Forwarded-Proto https;
            proxy_read_timeout 90s;
        }
    }
}

